// Medical Reading Practice Test 3. Original questions written for Valus from the HOSA 2026–27 test plan,
// slightly harder than the sample items and covering topics not used in Practice Tests 1–2.
import {q, mix} from './q.js';
const CA='Crisis Averted (Rivers)', TB='Everything Is Tuberculosis (Green)', FR='Fragmented (Yurkiewicz)', NP='The Next Patient (Grant)', GR='Grit (Duckworth)';
const CDC='CDC', WHO='World Health Organization', AHRQ='Agency for Healthcare Research and Quality', DUCK='Duckworth et al., grit research publications', VAL='Valus Medical Reading lessons';

export default {
 id:'medical-reading-3',
 event:'Medical Reading',
 title:'Practice Test 3',
 subtitle:'Background and ideas behind the five assigned books',
 minutes:60,
 sources:'the five assigned books’ subject areas, with background from the CDC, WHO, AHRQ and published grit research (study the books for chapter details)',
 plan:[{area:CA,weight:20},{area:TB,weight:20},{area:FR,weight:20},{area:NP,weight:20},{area:GR,weight:20}],
 questions:mix([
  q(CA,'A disease that is always present at a steady level in a region is called:','Endemic',['Epidemic','Pandemic','Sporadic'],'A','An epidemic is a rise above the expected level, and a pandemic spreads across regions.',CDC),
  q(CA,'In an outbreak, 30 of 200 people at a wedding become ill. What is the attack rate?','15%',['6%','30%','60%'],'B','Attack rate = ill ÷ exposed: 30 ÷ 200 = 0.15, or 15 percent of the people at the event.',CDC),
  q(CA,'What is the serial interval of an infectious disease?','Time between symptom onsets in linked cases',['Time from infection to full recovery','Number of new cases each week','Time until a vaccine is made'],'C','A short serial interval means the disease can spread through a community quickly.',CDC),
  q(CA,'Cases double every 3 days. Starting with 100 cases, about how many are expected after 9 days?','800',['300','400','900'],'D','Nine days is three doubling periods: 100 → 200 → 400 → 800, showing how fast growth can be.',CDC),
  q(CA,'A few infected people cause most new infections in an outbreak. What is this called?','Superspreading',['Herd immunity','Seasonal drift','Antigenic shift'],'A','Targeting high-risk settings like crowded indoor events can slow this kind of spread.',CDC),
  q(CA,'When a virus jumps from animals to humans, this event is called:','Zoonotic spillover',['Antibiotic resistance','Vertical transmission','Vaccine failure'],'B','Many emerging diseases, such as avian influenza, begin with spillover from animals.',WHO),
  q(CA,'Which approach links human, animal and environmental health to prevent outbreaks?','One Health',['Single Payer','Hospital Medicine','Primary Care'],'C','Monitoring farms, wildlife and people together can catch threats earlier.',CDC),
  q(CA,'Why do forecasters often combine several different models into one ensemble?','Combined models are usually more accurate',['It hides the uncertainty from the public','Each model is always wrong alone','It removes the need for any data'],'D','Ensembles balance the strengths and weaknesses of individual models.',CDC),
  q(CA,'How does a scenario projection differ from a forecast?','It shows “what if” outcomes under assumptions',['It predicts the exact future case number','It only uses data from past years','It ignores interventions completely'],'A','Scenarios help leaders compare choices, such as whether to add vaccines or close schools.',CDC),
  q(CA,'Which national reserve holds medicines and supplies for public health emergencies?','Strategic National Stockpile',['National Archives','Federal Reserve','National Weather Service'],'B','Stockpiles must be planned ahead because supplies can run short in a crisis.',CDC),
  q(TB,'Which form of TB resists isoniazid, rifampin and other key second-line drugs?','Extensively drug-resistant TB',['Latent TB infection','Drug-susceptible TB disease','Primary TB disease'],'C','XDR-TB is very hard to treat and shows why completing treatment matters.',WHO),
  q(TB,'TB of the lymph nodes in the neck was historically called scrofula or:','The king’s evil',['The white death','The black plague','The red fever'],'D','People once believed a royal touch could cure it, and kings held ceremonies to touch the sick.',WHO),
  q(TB,'TB that spreads to the spine and causes a curved back is called:','Pott’s disease',['Addison’s disease','Cushing’s disease','Hodgkin’s disease'],'A','TB can affect bones, kidneys, the brain and other organs, not just the lungs.',WHO),
  q(TB,'Which group of symptoms is most typical of active pulmonary TB?','Long cough, night sweats, weight loss',['Itchy rash, sneezing and watery eyes','Sudden chest pain only','Joint pain and morning stiffness'],'B','A cough lasting three weeks or more, sometimes with blood, should prompt TB testing.',CDC),
  q(TB,'What may a chest X-ray show in a patient with active TB?','Cavities in the upper lungs',['A broken collarbone','Fluid in the stomach','An enlarged heart only'],'C','X-rays support the diagnosis, but lab tests on sputum confirm it.',CDC),
  q(TB,'Which sample is usually tested to diagnose active pulmonary TB?','Sputum from the lungs',['A swab from the cheek','A strand of hair','A first-morning urine sample'],'D','Sputum smears, cultures and molecular tests look for TB bacteria directly.',CDC),
  q(TB,'Which rapid molecular test detects TB and rifampin resistance within hours?','GeneXpert',['Gram stain','Mantoux test','Blood culture'],'A','Fast detection of resistance helps patients start the right drugs sooner.',WHO),
  q(TB,'Bedaquiline drew attention when campaigners pushed to lower its price. What is it used to treat?','Drug-resistant TB',['Seasonal flu','Type 2 diabetes','High blood pressure'],'B','Access to newer drugs depends on price, patents and supply in poorer countries.',WHO),
  q(TB,'The WHO End TB Strategy aims to end the TB epidemic by about which year?','2035',['2005','2015','2100'],'C','Reaching the goal requires better diagnosis, treatment and social protection.',WHO),
  q(TB,'Why does undernutrition increase the risk of TB disease?','It weakens the immune system',['It kills TB bacteria','It improves lung function','It speeds up the TB vaccine'],'D','Food support can improve treatment results and lower the chance of disease.',WHO),
  q(FR,'A system that lets hospitals and clinics share patient records electronically is called a:','Health information exchange',['Health savings account','Hospital billing office','Medical device registry'],'A','Exchanges help prevent missing information when patients see many providers.',AHRQ),
  q(FR,'A patient has the same CT scan at two hospitals in one week. What fragmentation problem does this show?','Duplicate testing',['Proper continuity','Shared decision making','Medication reconciliation'],'B','Repeated tests add cost and radiation exposure without helping the patient.',AHRQ),
  q(FR,'A primary care doctor never receives the specialist’s findings after a referral. What has failed?','Closing the referral loop',['Opening a new chart','Ordering more lab tests','Billing the patient'],'C','Tracking referrals until results return keeps important findings from being lost.',AHRQ),
  q(FR,'Why is the fax machine often cited as a symbol of fragmented health care?','Records still move by fax between systems',['Fax is the newest medical technology','Faxes are always fully secure','Patients send faxes to doctors'],'D','Many systems still cannot share data electronically, so paper and fax fill the gap.',AHRQ),
  q(FR,'Many patients return to the hospital within 30 days of discharge. What is this measure called?','Readmission rate',['Mortality rate','Infection rate','Vaccination rate'],'A','Poor handoffs and confusing instructions after discharge raise readmissions.',AHRQ),
  q(FR,'A nurse visits patients at home after discharge to coordinate care. What model is this?','Transitional care',['Emergency triage','Hospice only','Fee-for-service'],'B','Transitional care programs have reduced readmissions for older adults.',AHRQ),
  q(FR,'A patient sees five specialists who each prescribe new drugs without coordinating. What risk grows?','Dangerous polypharmacy',['Better continuity','Lower drug costs','Fewer side effects'],'C','A single clinician reviewing all medicines can catch harmful interactions.',AHRQ),
  q(FR,'How does a shortage of primary care clinicians worsen fragmentation?','Fewer clinicians coordinate overall care',['More patients have one regular doctor','Specialists see fewer patients','Hospitals share records faster'],'D','Primary care often acts as the hub that ties specialist care together.',AHRQ),
  q(FR,'In a hospital, which physician is formally responsible for a patient’s overall care?','The attending of record',['The pharmacist on duty','The billing clerk','The transport aide'],'A','Patients can be confused about who is in charge when many teams are involved.',AHRQ),
  q(FR,'A national framework called TEFCA aims to help different networks:','Share health data with each other',['Set drug prices nationwide','License all U.S. physicians','Replace all hospitals'],'B','Common rules allow exchange across networks so records follow the patient.',AHRQ),
  q(NP,'A test with very high specificity is positive. What does this usually allow a clinician to do?','Rule the condition in',['Rule the condition out','Ignore the result','Stop all testing'],'C','The memory aid SpPIn means a specific test that is positive rules in disease.',AHRQ),
  q(NP,'A test says a healthy patient has a disease. What is this result called?','A false positive',['A true negative','A false negative','A true positive'],'D','False positives can lead to anxiety, more tests and unneeded treatment.',AHRQ),
  q(NP,'Ordering extra tests mainly to avoid lawsuits rather than to help the patient is called:','Defensive medicine',['Preventive medicine','Evidence-based care','Palliative care'],'A','It adds cost and can harm patients through false positives and procedures.',AHRQ),
  q(NP,'An overcrowded ED asks ambulances to go to other hospitals. What is this called?','Ambulance diversion',['Mutual aid','Direct admission','Patient boarding'],'B','Diversion can delay care for patients who must travel farther.',AHRQ),
  q(NP,'Under the Emergency Severity Index, a patient needing no resources, such as a simple prescription refill, is:','ESI level 5',['ESI level 1','ESI level 2','ESI level 3'],'C','Lower acuity patients may wait longer while sicker patients are treated first.',AHRQ),
  q(NP,'A clinician explains options and risks, then decides together with the patient. What is this?','Shared decision making',['Paternalistic care model','Defensive medicine','Anchoring bias'],'D','It is especially useful when several reasonable options exist.',AHRQ),
  q(NP,'Which campaign encourages clinicians and patients to avoid unnecessary tests and treatments?','Choosing Wisely',['Stop the Bleed','Just Say No','Click It or Ticket'],'A','Specialty groups list common tests that often add cost without benefit.',AHRQ),
  q(NP,'For a heart attack with a blocked artery, which measure tracks how fast the artery is reopened?','Door-to-balloon time',['Length of stay','Wait-room time','Billing cycle time'],'B','Faster reopening saves heart muscle, so EDs track this time closely.',AHRQ),
  q(NP,'Why can long shifts and constant interruptions raise diagnostic errors in the ED?','Fatigue and cognitive overload',['Too few patients to see','Too much sleep before work','Fewer decisions to make'],'C','Systems such as checklists and protected time can reduce these risks.',AHRQ),
  q(NP,'Why is the emergency department often called the “safety net” of health care?','It treats anyone, any time',['It sees only insured patients','It closes on weekends','It handles only minor injuries'],'D','People without insurance or a regular doctor often rely on the ED, as federal law requires screening for all.',AHRQ),
  q(GR,'How many items are on Duckworth’s Short Grit Scale?','8',['3','20','50'],'A','The original Grit Scale had 12 items; the short form keeps both facets.',DUCK),
  q(GR,'In Duckworth’s equations, talent times effort equals:','Skill',['Luck','Achievement','Passion'],'B','Skill times effort then equals achievement, so effort counts twice.',DUCK),
  q(GR,'Under Duckworth’s “Hard Thing Rule,” what must family members do?','Pick a challenging activity and stick with it',['Avoid any activity that feels too hard','Quit whenever practice feels boring','Let parents choose every activity'],'C','Each person chooses their own hard thing and may switch only at a natural stopping point.',DUCK),
  q(GR,'Animals that stop trying after repeated uncontrollable shocks show:','Learned helplessness',['Growth mindset','Deliberate practice','Intrinsic motivation'],'D','Martin Seligman’s research showed how lack of control can lead to giving up.',DUCK),
  q(GR,'Seeing setbacks as temporary and specific rather than permanent and pervasive reflects:','Optimistic explanatory style',['Pessimistic explanatory style','Fixed mindset thinking','Learned helplessness'],'A','Optimistic thinkers are more likely to keep trying after failure.',DUCK),
  q(GR,'Which parenting style, both supportive and demanding, does Duckworth link with grit?','Authoritative',['Permissive','Neglectful','Authoritarian'],'B','Warm but high-expectation parents help children build persistence.',DUCK),
  q(GR,'Research on extracurriculars found that which factor predicted later success?','Following through for multiple years',['Joining many clubs once','Never joining any activity','Quitting at the first sign of difficulty'],'C','Sticking with an activity for more than one year was linked to later achievement.',DUCK),
  q(GR,'According to Duckworth, how does passion for an interest usually develop?','Gradually, through discovery and deepening',['Instantly, in a single moment of insight','Only from inborn genetic talent','Only from strict parents'],'D','Interest grows through exploration, then practice and a sense of purpose.',DUCK),
  q(GR,'Why should the popular “10,000 hours” rule be used with caution?','Practice quality matters, not just hours',['No amount of practice helps a skill','Experts need only 100 hours','Talent alone explains success'],'A','Anders Ericsson stressed deliberate practice, not a fixed number of hours.',DUCK),
  q(GR,'In Duckworth’s view, what kind of purpose most supports long-term grit?','Purpose that helps other people',['Purpose focused only on fame','Purpose that changes daily','Purpose set by peers alone'],'B','Seeing how work benefits others makes hard work feel meaningful.',DUCK)
 ],7940)
};
